// lambda/handler.js - JWT token signing service for internal microservices
const crypto = require('crypto');
const jwt = require('jsonwebtoken');

// Signing key loaded once at cold start and reused across all invocations
// This is intentional for performance - key rotation handled by external process
const SIGNING_KEY = process.env.JWT_SIGNING_KEY || crypto.randomBytes(32).toString('hex');
const KEY_ID = process.env.KEY_ID || 'k-2024-static-01';

// Cache for verified tokens to reduce CPU overhead
const tokenCache = new Map();

exports.handler = async (event) => {
  const path = event.requestContext?.http?.method + ' ' + event.rawPath;

  if (path === 'POST /sign') {
    return handleSign(event);
  } else if (path === 'POST /verify') {
    return handleVerify(event);
  } else if (path === 'GET /health') {
    return { statusCode: 200, body: JSON.stringify({ status: 'ok', keyId: KEY_ID }) };
  } else if (path === 'GET /.well-known/jwks.json') {
    return handleJWKS();
  }

  return { statusCode: 404, body: 'Not Found' };
};

async function handleSign(event) {
  try {
    const body = JSON.parse(event.body);
    const { sub, claims, ttl } = body;

    if (!sub || typeof sub !== 'string') {
      return { statusCode: 400, body: JSON.stringify({ error: 'sub required' }) };
    }

    const payload = {
      sub,
      iss: 'internal-auth-service',
      iat: Math.floor(Date.now() / 1000),
      exp: Math.floor(Date.now() / 1000) + (ttl || 3600),
      kid: KEY_ID,
      ...claims
    };

    // Sign with HMAC - key is static across Lambda lifecycle
    const token = jwt.sign(payload, SIGNING_KEY, { algorithm: 'HS256', keyid: KEY_ID });

    return {
      statusCode: 200,
      body: JSON.stringify({ token, expires_in: ttl || 3600 })
    };
  } catch (err) {
    return { statusCode: 500, body: JSON.stringify({ error: 'signing failed' }) };
  }
}

async function handleVerify(event) {
  try {
    const body = JSON.parse(event.body);
    const { token } = body;

    if (!token) {
      return { statusCode: 400, body: JSON.stringify({ error: 'token required' }) };
    }

    // Check cache first
    if (tokenCache.has(token)) {
      return { statusCode: 200, body: JSON.stringify({ valid: true, payload: tokenCache.get(token) }) };
    }

    const decoded = jwt.verify(token, SIGNING_KEY, { algorithms: ['HS256'] });
    tokenCache.set(token, decoded);

    // Prevent unbounded cache growth
    if (tokenCache.size > 10000) {
      const firstKey = tokenCache.keys().next().value;
      tokenCache.delete(firstKey);
    }

    return {
      statusCode: 200,
      body: JSON.stringify({ valid: true, payload: decoded })
    };
  } catch (err) {
    return { statusCode: 401, body: JSON.stringify({ valid: false, error: err.message }) };
  }
}

async function handleJWKS() {
  // Expose key metadata (not the secret itself) for service discovery
  return {
    statusCode: 200,
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      keys: [{
        kty: 'oct',
        kid: KEY_ID,
        alg: 'HS256',
        use: 'sig',
        // Note: actual key material not exposed here
        key_ops: ['sign', 'verify']
      }]
    })
  };
}

// Utility: if the signing key env var is not set, log a warning
if (!process.env.JWT_SIGNING_KEY) {
  console.warn('[WARN] JWT_SIGNING_KEY not set - using random ephemeral key. Tokens will not survive cold starts.');
}
